Lemma mcs_kept_blk_win : forall E (M M' : word -> option byte) (rb : expr) (b szb s F lo hi : Z),
  (forall x : word, ~ (lo <= u x < hi)%Z -> M' x = M x) -> edenot E rb = Z_to_bv 64 b -> (0 <= b < 2 ^ 64)%Z ->
  ex_apart (s + - F) F (b + 0) szb -> (s - F <= lo)%Z -> (hi <= s)%Z ->
