(* [comment removed for export] *)
Ltac mcs_sc_hook :=
  lazymatch goal with
  | |- branch_taken BC_EQ (alu64 ALU_AND (Z_to_bv 64 (?p + ?k)) (Z_to_bv 64 ?mask)) (Z_to_bv 64 0) = false =>
      apply (mcs_and_eqF p k mask); [eassumption | vm_compute; reflexivity]
  | |- branch_taken BC_NE (alu64 ALU_AND (Z_to_bv 64 (?p + ?k)) (Z_to_bv 64 ?mask)) (Z_to_bv 64 0) = true =>
      apply (mcs_and_neT p k mask); [eassumption | vm_compute; reflexivity]
  | |- branch_taken BC_NE _ _ = false =>      (* [comment removed for export] *)
      repeat match goal with H : exW_canary _ _ ?m = exW_canary _ _ (c_m0 _) |- context [exW_canary _ _ ?m] => rewrite H end;
      apply mcs_bne_same
  end.


(* [comment removed for export] *)
Ltac mcs_drive_loop rounds fuel stops dirs fdef HK ST FZ :=
  first [ exb_at_stop stops ST | exb_at_jalr ST
        | lazymatch dirs with
          | ?d :: ?rest => exb_autoS rounds fuel stops (SCR [d] [] []) HK ST ltac:(fun _ => mcs_drive_loop rounds fuel stops rest fdef HK ST FZ)
          | _ => exb_fstep fdef HK ST FZ
          end ].
Ltac mcs_drive rounds fuel stops dirs fdef HK ST FZ :=
  exb_autoS rounds fuel stops (SCR [] [] []) HK ST ltac:(fun _ => mcs_drive_loop rounds fuel stops dirs fdef HK ST FZ).
